contract InvMutTest {
    C c;
    uint preBalance;
    uint seenBalanceInCallback;
    bool callbackFired;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        preBalance = address(c).balance;
        c.deposit{value: amount}();
        seenBalanceInCallback = 0;
        callbackFired = false;
        c.withdrawAll();
        assert(callbackFired && seenBalanceInCallback == preBalance - amount && address(c).balance == preBalance - amount);
    }
    receive() external payable {
        callbackFired = true;
        seenBalanceInCallback = address(c).balance;
    }
}
